CREATE TABLE IF NOT EXISTS stores (
 id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL, slug VARCHAR(80) NOT NULL UNIQUE,
 zone VARCHAR(80) NOT NULL DEFAULT 'America/Sao_Paulo', opens TIME NOT NULL DEFAULT '00:00', closes TIME NOT NULL DEFAULT '00:00',
 published BOOLEAN DEFAULT FALSE, taking BOOLEAN DEFAULT TRUE, tables_enabled BOOLEAN DEFAULT TRUE, kiosk_enabled BOOLEAN DEFAULT TRUE,
 table_pay VARCHAR(10) DEFAULT 'depois', kiosk_pay VARCHAR(10) DEFAULT 'antes', logo INT NULL,
 subscription VARCHAR(16) DEFAULT 'teste', expires DATE NOT NULL
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (
 id INT PRIMARY KEY AUTO_INCREMENT, store_id INT, name VARCHAR(100) NOT NULL, email VARCHAR(190) UNIQUE NOT NULL,
 hash VARCHAR(100) NOT NULL, role VARCHAR(16) NOT NULL, version INT DEFAULT 1, FOREIGN KEY(store_id) REFERENCES stores(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS images (id INT PRIMARY KEY AUTO_INCREMENT, store_id INT NOT NULL, data MEDIUMBLOB NOT NULL, FOREIGN KEY(store_id) REFERENCES stores(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id INT PRIMARY KEY AUTO_INCREMENT, store_id INT NOT NULL, name VARCHAR(90) NOT NULL, position INT DEFAULT 0, FOREIGN KEY(store_id) REFERENCES stores(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS products (id INT PRIMARY KEY AUTO_INCREMENT, store_id INT NOT NULL, category_id INT NOT NULL, name VARCHAR(100) NOT NULL, description VARCHAR(600) NOT NULL, price INT NOT NULL, promo INT, available BOOLEAN DEFAULT TRUE, image INT, groups_json JSON NOT NULL, FOREIGN KEY(store_id) REFERENCES stores(id), FOREIGN KEY(category_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS tables_rest (id INT PRIMARY KEY AUTO_INCREMENT, store_id INT NOT NULL, name VARCHAR(80) NOT NULL, token CHAR(36) UNIQUE NOT NULL, FOREIGN KEY(store_id) REFERENCES stores(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS orders (
 id INT PRIMARY KEY AUTO_INCREMENT, store_id INT NOT NULL, attempt CHAR(36) NOT NULL, token CHAR(64) UNIQUE NOT NULL,
 table_id INT, origin VARCHAR(100) NOT NULL, mode VARCHAR(20) NOT NULL, policy VARCHAR(10) NOT NULL,
 total INT NOT NULL, stage VARCHAR(20) NOT NULL, payment VARCHAR(20) NOT NULL DEFAULT 'pendente',
 method VARCHAR(20), cashier VARCHAR(100), paid_at DATETIME, created DATETIME DEFAULT (UTC_TIMESTAMP()),
 UNIQUE(store_id,attempt), INDEX(store_id,stage), FOREIGN KEY(store_id) REFERENCES stores(id)
) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS items (id INT PRIMARY KEY AUTO_INCREMENT, order_id INT NOT NULL, name VARCHAR(100) NOT NULL, base INT NOT NULL, options_json JSON NOT NULL, quantity INT NOT NULL, note VARCHAR(300) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS events (id INT PRIMARY KEY AUTO_INCREMENT, order_id INT NOT NULL, actor VARCHAR(100) NOT NULL, action VARCHAR(120) NOT NULL, reason VARCHAR(300), created DATETIME DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(order_id) REFERENCES orders(id)) ENGINE=InnoDB;

